SELECT * FROM quiz_progress WHERE user_id = #{userId}
AND consecutive_correct >= 3 AND consecutive_correct < 3
ORDER BY consecutive_correct ASC, last_quiz_at DESC

SELECT NOT EXISTS(
    SELECT 1 FROM cet6_word c
    LEFT JOIN quiz_progress p ON c.id = p.cet_word_id AND p.user_id = #{userId}
    WHERE p.id IS NULL OR p.consecutive_correct < 3
)
